// sketch: propagate(rule): if antecedent is T, set consequent to T; if consequent is F, fail
function propagate(state) {
  let changed = false;
  for (const r of rules) {
    if (r.antecedent(state) === true) {
      if (state[r.consequent] !== 'T') { state[r.consequent] = 'T'; changed = true; }
    }
  }
  return changed;
}
```

